// rtm-dual (ESM condition): what Node's ESM loader actually loads at runtime.
// `passengerFlag` is the passenger: nothing references it; only the
// resolver-trace-mismatch opacity keeps it alive.

export function entry(seed) {
  const table = ['prism', 'facet', 'lens', 'mirror', 'shard'];
  const text = String(seed);
  let acc = 67;
  for (let i = 0; i < text.length; i++) {
    acc = (acc * 109 + text.charCodeAt(i) * (i + 2)) % 8929;
  }
  const tag = table[acc % table.length];
  const rev = text.split('').reverse().join('');
  return 'rtm-dual:esm:entry:' + tag + ':' + acc + ':' + rev;
}

export function passengerFlag(seed) {
  const table = ['pennant', 'banner', 'ensign', 'jack', 'burgee'];
  const text = String(seed);
  let acc = 71;
  for (let i = 0; i < text.length; i++) {
    acc = (acc * 113 + text.charCodeAt(i) * (i + 3)) % 8837;
  }
  const tag = table[acc % table.length];
  const upper = text.toUpperCase();
  return 'rtm-dual:esm:passengerFlag:' + tag + ':' + acc + ':' + upper;
}
